fn frame(t: i32) {
    let w: i32 = host::display::width();
    host::display::clear(0x0d0f13);
    let a: i32 = host::display::state_get(1);
    let b: i32 = host::display::state_get(2);
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    host::display::state_set(0, down);
    let mut click: i32 = 0;
    if down == 1 && prev == 0 {
        click = 1;
    }

    if host::display::state_get(4) == 1 {
        if a > b {
            host::display::draw_string(130, 180, "TEAM A WINS", 0xffcc33, 3);
        } else {
            host::display::draw_string(130, 180, "TEAM B WINS", 0x33ff88, 3);
        }
        host::display::draw_number(170, 260, a, 0xffffff, 4);
        host::display::draw_string(240, 268, "TO", 0x556677, 2);
        host::display::draw_number(300, 260, b, 0xffffff, 4);
        host::display::draw_string(160, 380, "TAP FOR A NEW SET", 0x556677, 1);
        if click == 1 {
            host::display::state_set(1, 0);
            host::display::state_set(2, 0);
            host::display::state_set(3, 0);
            host::display::state_set(4, 0);
        }
    } else {
        host::display::fill_rect(0, 0, w / 2 - 2, 340, 0x1c1a10);
        host::display::fill_rect(w / 2 + 2, 0, w / 2 - 2, 340, 0x101c14);
        host::display::draw_string(90, 30, "TEAM A", 0xffcc33, 2);
        host::display::draw_number(90, 90, a, 0xffffff, 8);
        host::display::draw_string(346, 30, "TEAM B", 0x33ff88, 2);
        host::display::draw_number(346, 90, b, 0xffffff, 8);

        let serve: i32 = ((a + b) / 2) % 2;
        if serve == 0 {
            host::display::fill_rect(110, 250, 20, 20, 0xffffff);
        } else {
            host::display::fill_rect(366, 250, 20, 20, 0xffffff);
        }
        host::display::draw_string(200, 300, "DOT = SERVING", 0x556677, 1);

        host::display::fill_rect(196, 400, 120, 60, 0x232833);
        host::display::draw_string(224, 420, "UNDO", 0xffffff, 2);
        host::display::draw_string(140, 480, "FIRST TO 11 TAKES THE SET", 0x556677, 1);

        if click == 1 {
            let px: i32 = host::display::pointer_x();
            let py: i32 = host::display::pointer_y();
            if py < 340 {
                if px < w / 2 {
                    host::display::state_set(1, a + 1);
                    host::display::state_set(3, 1);
                    if a + 1 >= 11 {
                        host::display::state_set(4, 1);
                    }
                } else {
                    host::display::state_set(2, b + 1);
                    host::display::state_set(3, 2);
                    if b + 1 >= 11 {
                        host::display::state_set(4, 1);
                    }
                }
            } else if px >= 196 && px < 316 && py >= 400 && py < 460 {
                let last: i32 = host::display::state_get(3);
                if last == 1 && a > 0 {
                    host::display::state_set(1, a - 1);
                    host::display::state_set(3, 0);
                } else if last == 2 && b > 0 {
                    host::display::state_set(2, b - 1);
                    host::display::state_set(3, 0);
                }
            }
        }
    }
    host::display::present();
}
